		)

		sql, driver, err := db.Open(cfg.Database.URL)
		if err != nil {
			return fmt.Errorf("opening db: %w", err)
		}

		defer sql.Close()

		var store storage.Store

		switch driver {
		case db.SQLite:
			store = sqlite.NewStore(sql)
		case db.Postgres:
			store = postgres.NewStore(sql)
		case db.MySQL:
			store = mysql.NewStore(sql)
		}

		if cfg.Cache.Memory.Enabled {
